/**
 * Defines the structure of an index in IndexedDB,
 * including its name, key path, and optional parameters.
 */
type IndexedDbIndex = {
    name: string;
    keyPath: string;
    options?: IDBIndexParameters;
};

/**
 * Defines the properties required to initialize the useIndexedDb hook,
 * including the name of the object store to interact with, a list of
 * all available object stores, and optional indexes for querying the database.
 */
type HookProps = {
    objectStore: string;
    allObjectStores: string[];
    indexes?: IndexedDbIndex[];
};

/**
 * Defines the structure of the object returned by the useIndexedDb hook,
 * including the state of the hook, the items retrieved from IndexedDB,
 * any errors that occurred, and the functions to interact with the database.
 */
type UseIndexedDb<T> = {
    is: {
        saving: boolean;
        loading: boolean;
        deleting: boolean;
        querying: boolean;
        initialized: boolean;
    };
    items: T[] | null;
    dbError: Error | null;
    queryError: Error | null;
    saveItem: (q: T) => Promise<T>;
    removeItem: (id: string) => Promise<string>;
    updateItem: (q: T, id: string) => Promise<T>;
    loadItems: (filter?: (item: T) => boolean) => Promise<T[]>;
    isLocalId: (id: string, prefix?: string) => boolean;
    generateLocalId: (prefix?: string) => string;
    getItemsByIndex: (select: {
        index: IndexedDbIndex;
        id: string;
    }) => Promise<T[]>;
};

/**
 * Generates a special (UU)ID for locally stored entries,
 * which can be recognized again via `isLocalId()`.
 * @param prefix Optional prefix of the ID.
 * @returns {string} The generated ID.
 */
declare function generateLocalId(prefix?: string): string;
/**
 * Checks if the given ID was generated by `generateLocalId()`.
 * @param id The ID to check.
 * @param prefix Optional prefix of the ID.
 * @returns {boolean} true if the ID was generated locally, otherwise false.
 */
declare function isLocalId(id: string, prefix?: string): boolean;
declare function useIndexedDb<T extends {
    id: string;
}>(props: HookProps): UseIndexedDb<T>;

export { type HookProps, type IndexedDbIndex, type UseIndexedDb, generateLocalId, isLocalId, useIndexedDb };
